def eulerian_num(n, m):
    if n == 0 and m == 0:
        return 1
    if n == 0 or m == 0:
        return 0
    if m >= n:
        return 0
    # Eulerian number A(n, m) = (m+1)*A(n-1, m) + (n-m)*A(n-1, m-1)
