def smartNumber(n):
    """
    Find the n'th smart number.
    A smart number is a number that is divisible by at least two distinct prime numbers.
    """
    if n == 1:
        return 30

    # Generate smart numbers up to the n'th one
    # We need to find numbers divisible by at least 2 distinct primes

    # First, let's generate primes up to some limit
    # The 1000th smart number is 2664, so we need primes up to at least 2664

    def sieve(limit):
        is_prime = [True] * (limit + 1)
        is_prime[0] = is_prime[1] = False
        for i in range(2, int(limit ** 0.5) + 1):
            if is_prime[i]:
                for j in range(i * i, limit + 1, i):
                    is_prime[j] = False
        return [i for i, v in enumerate(is_prime) if v]

    # We'll incrementally check numbers and count how many are smart
    # A number is smart if it has at least 2 distinct prime factors

    def count_distinct_prime_factors(num, primes):
        count = 0
        for p in primes:
            if p * p > num:
                break
            if num % p == 0:
                count += 1
                while num % p == 0:
                    num //= p
            if count >= 2:
                return count
        if num > 1:
            count += 1
        return count

    # We need to find the n'th smart number
    # Let's estimate the upper bound
    # The 1000th smart number is 2664, so for larger n we may need more
    # Let's start with a reasonable limit and increase if needed

    limit = 10000
    while True:
        primes = sieve(limit)
        count = 0
        for num in range(2, limit + 1):
            if count_distinct_prime_factors(num, primes) >= 2:
                count += 1
                if count == n:
                    return num
        limit *= 2
