def get_total_number_of_sequences(n, m):
    if n == 0:
        return 0
    if n == 1:
        return m

    # dp[i][j] = number of sequences of length i ending with value j
    # j ranges from 1 to m
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for j in range(1, m + 1):
        dp[1][j] = 1

    for i in range(2, n + 1):
        for j in range(1, m + 1):
            # previous element p must satisfy: 2*p <= j <= m, so p <= j//2
            # and p >= 1
            # sum of dp[i-1][p] for p from 1 to j//2
            dp[i][j] = sum(dp[i - 1][p] for p in range(1, j // 2 + 1))

    return sum(dp[n])
