def find_minimum_range(arrays):
    if not arrays:
        return (0, 0)

    n = len(arrays)
    # Create a list of (value, array_index, element_index)
    elements = []
    for i, arr in enumerate(arrays):
        for j, val in enumerate(arr):
            elements.append((val, i, j))

    elements.sort()

    # Initialize pointers for each array
    pointers = [0] * n
    # Find the first element from each array
    for i in range(n):
        while pointers[i] < len(arrays[i]) and elements[pointers[i]][1] != i:
            pointers[i] += 1

    min_range = (float('inf'), float('-inf'))

    while True:
        # Find min and max among current elements
        current_min = min(elements[pointers[i]][0] for i in range(n))
        current_max = max(elements[pointers[i]][0] for i in range(n))

        if current_max - current_min < min_range[1] - min_range[0]:
            min_range = (current_min, current_max)

        # Find which array has the minimum value
        min_val = current_min
        min_array_idx = None
        for i in range(n):
            if elements[pointers[i]][0] == min_val:
                min_array_idx = i
                break

        # Advance the pointer of the array with the minimum value
        pointers[min_array_idx] += 1

