def zigzag(n, k):
    if k == 1:
        return 1
    if k > n:
        return 0
    # Entringer number: number of permutations of n elements with exactly k descents
    # Use dynamic programming
    # E(n, k) = k * E(n-1, k) + (n - k + 1) * E(n-1, k-1)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(0, min(i, k) + 1):
            if j == 0:
                dp[i][j] = 0
            else:
                dp[i][j] = j * dp[i - 1][j] + (i - j + 1) * dp[i - 1][j - 1]
    return dp[n][k]
```

