def find_ways(n):
    if n % 2 != 0:
        return 0
    k = n // 2
    # Count sequences of length n with non-negative prefix sums
    # This is related to Catalan numbers
    # For n=4, k=2, result=2
    # For n=6, k=3, result=5
    # For n=8, k=4, result=14
    # These are Catalan numbers: C_1=1, C_2=2, C_3=5, C_4=14
    # So find_ways(2k) = C_k
    def catalatal(m):
        if m == 0:
            return 1
        result = 1
        for i in range(1, m + 1):
            result = result * (m + i) // i
        return result // (m + 1)
    return catalatal(k)
