def get_maxgold(grid, rows, cols):
    if rows == 0 or cols == 0:
        return 0

    # dp[i][j] = maximum gold collected starting from cell (i, j)
    dp = [[0] * cols for _ in range(rows)]

    # Fill from right to left, bottom to top
    for i in range(rows - 1, -1, -1):
        for j in range(cols - 1, -1, -1):
            if j == cols - 1:
                # Can only go down or up
                if i == rows - 1:
                    dp[i][j] = grid[i][j]
                else:
                    dp[i][j] = grid[i][j] + max(dp[i + 1][j] if i + 1 < rows else 0,
                                                  dp[i - 1][j] if i - 1 >= 0 else 0)
            else:
                # Can go right, down-right, or up-right
                right = dp[i][j + 1]
                down_right = dp[i + 1][j + 1] if i + 1 < rows else 0
                up_right = dp[i - 1][j + 1] if i - 1 >= 0 else 0
                dp[i][j] = grid[i][j] + max(right, down_right, up_right)

    # The answer is the maximum value in the first column
    return max(dp[i][0] for i in range(rows))
