def tuple_intersection(t1, t2):
    def normalize(t):
        return tuple(sorted(t))

    set1 = {normalize(t) for t in t1}
    set2 = {normalize(t) for t in t2}

    common = set1 & set2

    # Return the original tuples from t1 that match the common normalized tuples
    result = set()
    for t in t1:
        if normalize(t) in common:
            result.add(t)

    return result
