def is_subset_sum(arr, n, target):
    # dp[i][j] = True if there is a subset of arr[0..i-1] with sum j
    dp = [[False] * (target + 1) for _ in range(n + 1)]

    # Base case: sum 0 is always possible with empty subset
    for i in range(n + 1):
        dp[i][0] = True

    for i in range(1, n + 1):
        for j in range(1, target + 1):
            # Not take arr[i-1]
            dp[i][j] = dp[i - 1][j]
            # Take arr[i-1] if it doesn't exceed target
